def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # DP array where dp[j] is the maximum volume that can be achieved with total capacity j
    dp = [0] * (V + 1)
    for vol in volumes[:n]:
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol] + vol > dp[j]:
                dp[j] = dp[j - vol] + vol
    max_occupied = max(dp)
    return V - max_occupied

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
