        new_dp = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                new_dp[j] = prefix[j]
            else:
                new_dp[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp = new_dp
    return dp[m] % MOD

